import{_ as e,r as n,o,c,e as s,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"部件 - October CMS - 2.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"渲染部件","slug":"渲染部件","link":"#渲染部件","children":[]},{"level":2,"title":"将变量传递给部件","slug":"将变量传递给部件","link":"#将变量传递给部件","children":[{"level":3,"title":"将标记作为变量传递","slug":"将标记作为变量传递","link":"#将标记作为变量传递","children":[]}]},{"level":2,"title":"动态部件","slug":"动态部件","link":"#动态部件","children":[{"level":3,"title":"部件执行生命周期","slug":"部件执行生命周期","link":"#部件执行生命周期","children":[]},{"level":3,"title":"生命周期限制","slug":"生命周期限制","link":"#生命周期限制","children":[]}]}],"relativePath":"2.x/zh-cn/cms/partials.md","filePath":"2.x/zh-cn/cms/partials.md"}'),u={name:"2.x/zh-cn/cms/partials.md"};function r(g,a,k,d,m,h){const t=n("pre-heading"),p=n("post-heading");return o(),c("div",null,[s(t),a[0]||(a[0]=l("h1",null,"部件",-1)),s(p),a[1]||(a[1]=i(`<p>部件包含可重用的代码块，可在整个网站的任何地方使用。 它们对于在不同页面或布局上重复的元素很有用。 一个这样的例子是跨不同<a href="./layouts.html">页面布局</a>使用的页脚。 在<a href="./../ajax/update-partials.html">使用 AJAX 更新页面内容</a> 时，部件也是一个关键因素。</p><p>部件模板文件位于主题的 <strong>partials</strong> 目录中。 部件文件应具有 <strong>htm</strong> 扩展名。 接下来是最简单的部件示例。</p><div class="language- extra-class"><pre class="language-text"><code>&lt;p&gt;这是部件&lt;/p&gt;
</code></pre></div><p><a href="./themes.html#oc-configuration-section">Configuration</a> 配置部分对于部件是可选的，并且可以包含显示在后端用户界面中的可选 <strong>description</strong> 参数。 此示例显示了定义了描述的部分。</p><div class="language- extra-class"><pre class="language-text"><code>description = &quot;演示部件&quot;
==
&lt;p&gt;这是部件&lt;/p&gt;
</code></pre></div><p>部件配置部分还可以包含组件定义。 <a href="./components.html">组件文章</a> 更详细地解释了组件。</p><h2 id="渲染部件"><a href="#渲染部件" class="header-anchor">#</a> 渲染部件</h2><p><code>{% partial &quot;partial-name&quot; %}</code> Twig 标签呈现部件。 该标签有一个必需的参数：不带扩展名的部件文件名。 请记住，如果您从 <a href="./themes.html#oc-subdirectories">子目录</a> 引用部件，您应该指定子目录名称。 <code>{% partial %}</code> 标签可以在页面、布局或其他部件中使用。 引用部件的页面示例：</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>sidebar<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>sidebar-contacts<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p><a id="oc-passing-variables-to-partials"></a></p><h2 id="将变量传递给部件"><a href="#将变量传递给部件" class="header-anchor">#</a> 将变量传递给部件</h2><p>你会发现你经常需要将变量从外部代码传递给部件代码。 这使得分音更加有用。 例如，您可以有一个部件来呈现博客文章列表。 如果您可以将帖子集合传递给部件，则可以在博客存档页面、博客类别页面等上使用相同的部件。 您可以通过在 <code>{% partial %}</code> 标签中的部件名称之后指定变量来将变量传递给部分：</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>sidebar<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>blog-posts<span class="token punctuation">&quot;</span></span> posts<span class="token operator">=</span>posts <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>您还可以分配新变量以用于部件：</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>sidebar<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>sidebar-contacts<span class="token punctuation">&quot;</span></span> city<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>Vancouver<span class="token punctuation">&quot;</span></span> country<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>Canada<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>在部件内部，可以像访问任何其他标记变量一样访问变量：</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>国家: <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> country <span class="token delimiter punctuation">}}</span></span>, 城市: <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> city <span class="token delimiter punctuation">}}</span></span>.<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h3 id="将标记作为变量传递"><a href="#将标记作为变量传递" class="header-anchor">#</a> 将标记作为变量传递</h3><p>通过将<code>body</code> 属性添加到partial 标签，可以将标记传递给部件。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>card<span class="token punctuation">&quot;</span></span> body <span class="token delimiter punctuation">%}</span></span>
    这是卡片内容
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endpartial</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>内容在部件内部作为 <code>body</code> 变量可用。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> body<span class="token operator">|</span>raw <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><p>结合 <a href="./../markup/tag-placeholder.html">占位符标记</a>，这可以让您构建可组合的部件。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>card<span class="token punctuation">&quot;</span></span> image<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>img.jpg<span class="token punctuation">&quot;</span></span> body <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">put</span> header <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h2</span><span class="token punctuation">&gt;</span></span>这是卡头<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h2</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endput</span> <span class="token delimiter punctuation">%}</span></span>
    这是卡片内容
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endpartial</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p><strong>card</strong> 部件由两个内容区域和一个图像变量组成。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>header<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>image<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> image <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">placeholder</span> header <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>body<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> body<span class="token operator">|</span>raw <span class="token delimiter punctuation">}}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p><a id="oc-dynamic-partials"></a></p><h2 id="动态部件"><a href="#动态部件" class="header-anchor">#</a> 动态部件</h2><p>部件像页面一样，可以使用任何 Twig 功能。 详情请参考<a href="./pages.html#oc-dynamic-pages">动态页面</a> 文档。</p><h3 id="部件执行生命周期"><a href="#部件执行生命周期" class="header-anchor">#</a> 部件执行生命周期</h3><p>部件函数的 PHP 部分可以定义一些特殊的函数：<code>onStart</code> 和 <code>onEnd</code>。 <code>onStart</code> 函数在部件渲染之前和部件<a href="./components.html">组件</a> 执行之前执行。 <code>onEnd</code> 函数在部件渲染之前和部件 <a href="./components.html">组件</a> 执行之后执行。 在 onStart 和 onEnd 函数中，您可以将变量注入 Twig 环境。 使用 <code>数组</code> 将变量传递给页面：</p><div class="language- extra-class"><pre class="language-text"><code>==
function onStart()
{
    $this[&#39;hello&#39;] = &quot;Hello world!&quot;;
}
==
&lt;h3&gt;{{ hello }}&lt;/h3&gt;
</code></pre></div><p><a href="./../markup.html">标记指南</a> 中描述了 October 提供的模板语言。 <a href="./layouts.html#oc-dynamic-layouts">动态布局</a> 文章中描述了处理程序执行的整体顺序。</p><h3 id="生命周期限制"><a href="#生命周期限制" class="header-anchor">#</a> 生命周期限制</h3><p>由于它们的实例化较晚，因此在页面呈现期间，部件对象的生命周期存在一些限制。 它们不遵循标准执行流程，如<a href="./layouts.html#oc-dynamic-layouts">布局执行生命周期</a> 中所述。 应注意以下限制：</p><ol><li>AJAX 事件未注册，无法正常运行。</li><li>生命周期函数不能返回任何值。</li><li>正常的 POST 表单处理将在部分渲染时发生。</li></ol><p>通常，部件中的组件使用是为基本组件设计的，这些组件无需太多处理即可呈现简单的标记，例如 <em>Like</em> 或 <em>Tweet</em> 按钮。</p>`,37))])}const q=e(u,[["render",r]]);export{v as __pageData,q as default};
